import 'package:flutter/material.dart';
import '../services/krevzy_social_settings_service.dart';
class TagsMentionsScreen extends StatefulWidget{const TagsMentionsScreen({super.key});@override State<TagsMentionsScreen>createState()=>_TagsMentionsScreenState();}
class _TagsMentionsScreenState extends State<TagsMentionsScreen>{String tags='Everyone',mentions='Everyone';bool approval=false,loading=true;final choices=['Everyone','People you follow','No one'];@override void initState(){super.initState();_load();}Future<void>_load()async{try{final d=await KrevzySocialSettingsService.getSettings();if(!mounted)return;setState((){tags=d['tags']?.toString()??'Everyone';mentions=d['mentions']?.toString()??'Everyone';approval=d['manual_tag_approval'] as bool? ?? false;loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}Future<void>_save(String k,dynamic v)async{try{await KrevzySocialSettingsService.setValue(k,v);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Setting saved.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Unable to save: $e')));}}Widget row(String t,String k,String v){return ListTile(title:Text(t),subtitle:Text(v),trailing:DropdownButton<String>(value:choices.contains(v)?v:choices.first,items:choices.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(x){if(x==null)return;setState(()=>k=='tags'?tags=x:mentions=x);_save(k,x);}));}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tags and mentions')),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:[row('Who can tag you','tags',tags),row('Who can mention you','mentions',mentions),SwitchListTile(title:const Text('Manual approval'),subtitle:const Text('Approve tagged content before it appears on your profile.'),value:approval,onChanged:(v){setState(()=>approval=v);_save('manual_tag_approval',v);})]));}
